['codigo' => 'VCP-9-08', 'titulo' => 'Aplicación para una necesidad de la comunidad escolar',
 'objeto' => 'la aplicación para la comunidad escolar',
 'resumen' => 'Proyecto insignia de 9.º: detectar una necesidad real dentro del colegio y resolverla con una aplicación web completa.',
