['codigo' => 'VCP-9-09', 'titulo' => 'Agente con herramientas: el tutor de matemáticas',
 'objeto' => 'el agente tutor',
 'resumen' => 'Agente que resuelve con una calculadora propia en lugar de improvisar, y que guía en vez de dar la respuesta.',
 'descripcion' => '<p>El estudiante construye un agente al que se le entregan herramientas: una función que calcula, otra que verifica un resultado. El agente decide cuándo usarlas. La comparación con un agente sin herramientas es reveladora: el segundo se equivoca en aritmética larga con una seguridad absoluta.</p><p>El segundo eje es pedagógico: el tutor no puede dar la respuesta final. Debe devolver una pista, una pregunta o un paso. El estudiante escribe esa restricción, la prueba con compañeros reales y mide cuántos consiguieron llegar solos a la respuesta.</p>',
 'pregunta' => '¿Cuándo debe una máquina calcular y cuándo debe callarse y preguntar?',
 'contexto' => 'Innovación científica y técnica', 'concepto' => 'Sistemas',
 'perfil' => 'Íntegro|Pensador|Solidario', 'atl' => 'Pensamiento crítico|Reflexión',
 'objetivos' => 'Definir herramientas que un agente puede invocar|Restringir el comportamiento del agente por diseño|Comparar respuestas con y sin herramienta|Medir el efecto pedagógico con usuarios reales',
 'entregables' => 'Herramienta de cálculo programada|Ficha del agente con la regla de no dar la respuesta|Comparación de veinte respuestas con y sin herramienta|Prueba con tres compañeros',
 'lenguaje' => 'Python', 'dificultad' => 'avanzado', 'sesiones' => 5, 'horas' => 5.0, 'ia' => 1,
 'codigo_inicial' => "def calcular(expresion):\n    \"\"\"Herramienta que el agente puede invocar. Solo aritmetica basica.\"\"\"\n    permitido = set(\"0123456789+-*/(). \")\n    if not set(expresion) <= permitido:\n        return \"expresion no permitida\"\n    return str(eval(expresion))\n\n# TODO: describe la herramienta al agente\n# TODO: regla: nunca dar el resultado final del ejercicio del estudiante",
 'fases' => [
   ['indagar', 'Dónde falla un modelo sin herramientas', 'Plantea a un modelo diez operaciones aritméticas largas y verifica cada resultado con una calculadora. Registra la tasa de error y el tipo de error.', 'Tabla de diez operaciones con la tasa de error medida.', 45],
   ['desarrollar', 'Diseñar la herramienta y la restricción', 'Define la firma de la herramienta, qué acepta y qué rechaza. Redacta la regla que impide dar la respuesta final y las tres formas de ayuda permitidas.', 'Especificación de la herramienta y ficha del agente con la restricción.', 50],
   ['crear', 'Conectar agente y herramienta', 'Implementa la herramienta con validación de entrada y configura el agente para usarla. Prueba las mismas diez operaciones de la fase de indagación.', 'Herramienta funcionando y las diez operaciones con resultado correcto.', 80],
   ['evaluar', 'Prueba con tres compañeros', 'Tres compañeros usan el tutor con un ejercicio real. Mide cuántos llegaron solos a la respuesta y cuántas veces el agente rompió su propia regla. Corrige y vuelve a probar una vez.', 'Registro de las tres sesiones, roturas de la regla y corrección aplicada.', 55],
 ],
 'recursos' => [
   ['lectura', 'Agentes con herramientas', 'Cómo se describe una herramienta y cuándo el modelo decide usarla.'],
   ['lectura', 'Riesgos de eval y cómo acotarlo', 'Por qué la validación de la expresión es obligatoria.'],
 ]],

['codigo' => 'VCP-9-10', 'titulo' => 'Control de versiones y trabajo en equipo',
 'objeto' => 'el repositorio del equipo',
 'resumen' => 'Trabajar en equipo sobre el mismo código con Git: ramas, fusiones y la resolución de un conflicto provocado a propósito.',
 'descripcion' => '<p>Tres estudiantes trabajan sobre el mismo proyecto. Cada uno desarrolla en su rama y luego integran. El docente provoca deliberadamente un conflicto haciendo que dos personas modifiquen la misma función, y el equipo debe resolverlo sin perder el trabajo de nadie.</p><p>El aprendizaje central no es la sintaxis de los comandos sino el acuerdo: qué se escribe en un mensaje de confirmación, cuándo se integra, quién revisa. El equipo redacta su propio acuerdo de trabajo y lo evalúa al final del proyecto.</p>',
 'pregunta' => '¿Cómo trabajamos tres personas sobre el mismo archivo sin destruir el trabajo de los demás?',
 'contexto' => 'Identidades y relaciones', 'concepto' => 'Sistemas',
 'perfil' => 'Solidario|Buen comunicador|Íntegro', 'atl' => 'Colaboración|Organización|Comunicación',
 'objetivos' => 'Registrar cambios con mensajes útiles|Trabajar en ramas y fusionarlas|Resolver un conflicto conservando ambos aportes|Acordar y evaluar una forma de trabajo en equipo',
 'entregables' => 'Repositorio con al menos quince confirmaciones de tres autores|Registro del conflicto resuelto|Acuerdo de trabajo del equipo y su evaluación final',
 'lenguaje' => 'Git', 'dificultad' => 'intermedio', 'sesiones' => 4, 'horas' => 4.0, 'ia' => 0,
 'codigo_inicial' => "# Flujo acordado por el equipo\ngit checkout -b funcion-nueva\n# ... editar ...\ngit add archivo.py\ngit commit -m \"Agrega validacion de cupo maximo\"\ngit checkout main\ngit merge funcion-nueva\n# TODO: documenta que hace tu equipo cuando aparece un conflicto",
 'fases' => [
   ['indagar', 'Cómo se pierde el trabajo', 'Recuerda o investiga tres formas reales de perder trabajo en equipo (sobrescribir un archivo compartido, versiones con nombres distintos, copias en distintos computadores). Explica el costo de cada una.', 'Análisis de tres formas de pérdida con su costo.', 40],
   ['desarrollar', 'Acuerdo de trabajo del equipo', 'Redacta con tu equipo el acuerdo: cómo se nombran las ramas, qué debe decir un mensaje de confirmación, cuándo se integra a la rama principal, quién revisa.', 'Acuerdo escrito y firmado por los tres integrantes.', 40],
   ['crear', 'Trabajar en ramas e integrar', 'Cada integrante desarrolla una funcionalidad en su rama con al menos cinco confirmaciones. Integren las tres ramas y resuelvan el conflicto provocado sin perder trabajo.', 'Repositorio con quince confirmaciones y el conflicto resuelto documentado.', 85],
   ['evaluar', 'Revisar el acuerdo con evidencia', 'Revisen el historial: ¿los mensajes explican el cambio? ¿alguien integró sin avisar? Evalúen cada punto del acuerdo con evidencia del repositorio y propongan dos ajustes.', 'Evaluación del acuerdo con evidencia y dos ajustes propuestos.', 45],
 ],
 'recursos' => [
   ['lectura', 'Git en diez comandos', 'Los comandos que realmente se usan en el aula.'],
   ['lectura', 'Cómo escribir un mensaje de confirmación', 'Qué cambió y por qué, en una línea.'],
 ]],

];
